/** Explicit queued background work on imported/recorded sources; no cron or automatic dispatch activation. */
final class ResearchExecution {
 public function __construct(private ?OfflineResearchTransport $simulator=null){}
 public function plan(string $shop,string $source,array $run):array|WP_Error {
  $gate=ResearchExecutionJournal::access($shop);if($gate instanceof WP_Error)return $gate;$r=(new CommercialResearchRepository())->read($shop,$source);if($r instanceof WP_Error)return $r;if($r['record']['stage']!=='RESEARCH_READY')return self::error('source_stage');$normalized=AiRunContext::normalize((string)($run['run_id']??''),(string)($run['started_at']??''));if($normalized instanceof WP_Error)return $normalized;
  $p=(new ShopAiGovernanceRepository())->evaluate($shop,'production',$normalized);if($p instanceof WP_Error)return $p;$binding=$p['stages']['research']['task_binding']??null;if(!is_array($binding))return self::error('reviewed_model_required');$route=StageTaskBinding::load($binding);if($route instanceof WP_Error)return $route;
  global $wpdb;$wpdb->last_error='';$row=$wpdb->get_row($wpdb->prepare('SELECT policy,policy_hash,state FROM '.Tables::shop_ai_policies().' WHERE shop_key=%s AND environment=%s',$shop,'production'),ARRAY_A);if($wpdb->last_error!==''||!is_array($row)||$row['state']!=='ACTIVE'||hash('sha256',$row['policy'])!==$row['policy_hash'])return self::error('policy');
  return OpenAIClient::generationContract(CommercialResearchContract::researchPrompt($r['record']['research']),4000,true,false,$route['provider_model'])+['policy_sha256'=>$row['policy_hash'],'routing_decision'=>$route,'source_acquisition'=>'RECORDED_OR_MANUAL_IMPORT_NOT_LIVE_FETCH','prompt_policy_version'=>'source-grounded-background-v1'];
 }
 public function enqueue(string $shop,array $sources,array $options,array $run,string $requestKey):array|WP_Error {
  $gate=ResearchExecutionJournal::access($shop);if($gate instanceof WP_Error)return $gate;
  if(!array_is_list($sources)||$sources===[]||count($sources)>5||count(array_unique($sources,SORT_REGULAR))!==count($sources)||count($options)!==5||array_diff(array_keys($options),['version','max_opportunities','freshness_days','per_task_ceiling','currency'])||($options['version']??null)!=='shop2-research-run-v1'||!is_int($options['max_opportunities']??null)||$options['max_opportunities']<1||$options['max_opportunities']>5||count($sources)>$options['max_opportunities']||!is_int($options['freshness_days']??null)||$options['freshness_days']<1||$options['freshness_days']>90||!is_string($options['currency']??null)||preg_match('/^[A-Z]{3}$/D',$options['currency'])!==1)return self::error('bounded_request');$amount=MonetaryReservationRepository::micros($options['per_task_ceiling']??null);if($amount instanceof WP_Error||$amount<1)return self::error('task_ceiling');
  $ctx=AiRunContext::normalize((string)($run['run_id']??''),(string)($run['started_at']??''));if($ctx instanceof WP_Error)return $ctx;$contracts=[];$fingerprints=[];
  foreach($sources as $source){if(!is_string($source))return self::error('source');$fresh=$this->fresh($source,$options['freshness_days']);if($fresh instanceof WP_Error)return $fresh;$f=CommercialResearchContract::fingerprint($fresh['record']['research']);if(in_array($f,$fingerprints,true))return self::error('duplicate_candidate');$fingerprints[]=$f;$c=$this->plan($shop,$source,$ctx);if($c instanceof WP_Error)return $c;$contracts[]=$c;}
  return (new ResearchExecutionJournal())->create(['version'=>'shop2-research-queue-v1','shop_key'=>$shop,'actor_id'=>get_current_user_id(),'mode'=>$this->simulator===null?'NETWORK':'OFFLINE_SIMULATOR','sources'=>$sources,'contracts'=>$contracts,'options'=>$options,'run_context'=>$ctx],$requestKey);
 }
 public function read(string $shop,int $id):array|WP_Error {$gate=ResearchExecutionJournal::access($shop);return $gate instanceof WP_Error?$gate:(new ResearchExecutionJournal())->read($id);}
 public function step(string $shop,int $id,string $expected):array|WP_Error {
  return $this->process($shop,$id,function()use($shop,$id,$expected){global $wpdb;$j=new ResearchExecutionJournal();$v=$j->read($id);if($v instanceof WP_Error)return $v;if($v['event_sha256']!==$expected||!in_array($v['state'],['QUEUED','WAITING'],true))return self::error('stale_or_terminal');$i=$v['identity'];$mode=$this->simulator===null?'NETWORK':'OFFLINE_SIMULATOR';if($mode!==$i['mode'])return self::error('mode');
   // A request cannot select a simulator or turn a server/network switch on.
   if($mode==='NETWORK'&&(!defined('DIGIFORGE_RESEARCH_BACKGROUND_EXECUTION_AUTHORIZED')||DIGIFORGE_RESEARCH_BACKGROUND_EXECUTION_AUTHORIZED!==true||!GovernedResearchProvider::executionAllowed()))return self::error('network_locked');
   $source=$i['sources'][$v['index']];$fresh=$this->fresh($source,$i['options']['freshness_days']);if($fresh instanceof WP_Error)return $fresh;$contract=$this->plan($shop,$source,$i['run_context']);if($contract instanceof WP_Error)return $contract;if(Validator::canonicalJson($contract)!==Validator::canonicalJson($i['contracts'][$v['index']]))return self::error('policy_or_request_changed');
   $money=new MonetaryReservationRepository();$quote=null;
   if($v['state']==='QUEUED'){$gov=new ShopAiGovernanceRepository();$p=$gov->evaluate($shop,'production',$i['run_context']);if($p instanceof WP_Error)return $p;foreach(['run','day','month']as $period)if(($p['budgets'][$period]??0)<=0)return self::error('hard_budget_required');if(($p['stages']['research']['monthly_budget']??null)===null||$p['currency']!==$i['options']['currency'])return self::error('workflow_budget_required');$bound=$money->findQuote($shop,$contract,false);if($bound instanceof WP_Error)return $bound;$max=MonetaryReservationRepository::micros($bound['quote_preview']['maximum_charge']);$limit=MonetaryReservationRepository::micros($i['options']['per_task_ceiling']);if($max instanceof WP_Error||$limit instanceof WP_Error||$max>$limit||$bound['quote_preview']['currency']!==$i['options']['currency'])return self::error('task_ceiling');$quote=$money->findQuote($shop,$contract);if($quote instanceof WP_Error)return $quote;}
   $lease=$this->claim($id,$v['state']);if($lease instanceof WP_Error)return $lease;
   try{
    if($v['state']==='QUEUED'){
     $v=$j->append($id,$v['event_sha256'],['state'=>'RESERVING','usage_id'=>0,'response_id'=>null,'poll_count'=>0,'simulation_usage'=>null,'result_model'=>null,'provider_response_sha256'=>null,'result_payload'=>null]);if($v instanceof WP_Error)return $v;
     $usage=(new ShopAiGovernanceRepository())->reserveGeneration($shop,'research','research-queue-'.$id.'-'.$v['index'],$i['run_context'],$quote,$contract);if($usage instanceof WP_Error){$blocked=$j->append($id,$v['event_sha256'],['state'=>'BLOCKED','failure_class'=>'RESERVATION_DENIED_OR_UNCERTAIN']);return $blocked instanceof WP_Error?$blocked:$usage;}if(!empty($usage['idempotent_replay']))return $this->unknown($v,'RESERVATION_REPLAY_UNKNOWN');
     $v=$j->append($id,$v['event_sha256'],['state'=>'RESERVED','usage_id'=>(int)$usage['id']]);if($v instanceof WP_Error)return $v;$v=$j->append($id,$v['event_sha256'],['state'=>'DISPATCHING']);if($v instanceof WP_Error)return $v;
     try{$response=$this->simulator!==null?$this->simulator->start($contract):(new OpenAIClient())->startBackgroundDevelop(CommercialResearchContract::researchPrompt($fresh['record']['research']),4000,$contract['model']);}catch(\Throwable){$response=self::error('transport_unknown');}
    }else{
     $v=$j->append($id,$v['event_sha256'],['state'=>'POLLING','poll_count'=>$v['poll_count']+1]);if($v instanceof WP_Error)return $v;
     try{$response=$this->simulator!==null?$this->simulator->poll($v['response_id'],$contract):(new OpenAIClient())->retrieveBackground($v['response_id']);}catch(\Throwable){$response=self::error('transport_unknown');}
    }
    if(!$this->leaseValid($id,$lease)||ResearchExecutionJournal::access($shop)!==true)return $this->unknown($v,'AUTHORITY_OR_LEASE_CHANGED');
    if($response instanceof WP_Error)return $this->unknown($v,'PROVIDER_OUTCOME_UNKNOWN');
    if(!is_string($response['response_id']??null)||preg_match('/^resp_[A-Za-z0-9_-]{1,180}$/D',$response['response_id'])!==1||($v['response_id']!==null&&$v['response_id']!==$response['response_id']))return $this->unknown($v,'PROVIDER_IDENTITY_INVALID');
    if($mode==='NETWORK'){$meter=(new ProviderEvidenceRepository())->recordOutcome($v['usage_id'],$shop,$response);if($meter instanceof WP_Error)return $this->unknown($v,'METERING_UNKNOWN');}
    if(in_array($response['status']??null,['queued','in_progress'],true))return $j->append($id,$v['event_sha256'],['state'=>$v['poll_count']>=5?'HELD':'WAITING','response_id'=>$response['response_id']]);
    try{if(($response['status']??null)!=='completed'||($response['model']??null)!==$contract['model']||!is_array($response['payload']??null)||!is_string($response['provider_response_sha256']??null)||preg_match('/^[a-f0-9]{64}$/D',$response['provider_response_sha256'])!==1)throw new \InvalidArgumentException();$parsed=CommercialResearchContract::response(CommercialResearchContract::json($response['payload']),$fresh['record']['research']);$tokens=$response['usage']??null;if(!is_array($tokens)||!is_int($tokens['input_tokens']??null)||!is_int($tokens['output_tokens']??null)||!is_int($tokens['total_tokens']??null)||min($tokens['input_tokens'],$tokens['output_tokens'])<0||$tokens['total_tokens']!==$tokens['input_tokens']+$tokens['output_tokens'])throw new \InvalidArgumentException();}catch(\Throwable){return $this->unknown($v,'MALFORMED_OR_UNGROUNDED_RESULT');}
    $v=$j->append($id,$v['event_sha256'],['state'=>'INTAKING','response_id'=>$response['response_id'],'result_model'=>$response['model'],'provider_response_sha256'=>$response['provider_response_sha256'],'result_payload'=>['scores'=>$parsed['scores'],'concepts'=>$parsed['concepts']],'simulation_usage'=>$mode==='OFFLINE_SIMULATOR'?$tokens:null]);if($v instanceof WP_Error)return $v;
    $result=(new CommercialResearchRepository())->importQueuedResult($shop,$id,$source,$v['event_sha256']);if($result instanceof WP_Error)return $this->unknown($v,'RESULT_INTAKE_UNKNOWN');$results=$v['results'];$results[]=['source_sha256'=>$source,'result_sha256'=>$result['hash'],'intake_event_sha256'=>$v['event_sha256'],'usage_id'=>$v['usage_id'],'mode'=>$mode,'simulation_usage'=>$mode==='OFFLINE_SIMULATOR'?$tokens:null];$next=$v['index']+1;
    return $j->append($id,$v['event_sha256'],['state'=>$next===count($i['sources'])?'AWAITING_REVIEW':'QUEUED','index'=>$next,'results'=>$results]);
   }finally{$wpdb->last_error='';$rootState=$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::jobs().' WHERE id=%d',$id));if($wpdb->last_error!==''||!is_string($rootState))return self::error('lease_state_unknown');if($rootState!=='RUNNING'&&!(new JobRepository())->releaseLease($id,$lease))return self::error('lease_release_unknown'); // Retain expiry on interrupted active stages so bounded recovery remains possible.
   }
  });
 }
 /** Read-only operator projection. Simulated tokens never become provider metering or actual charges. */
 public function costEvidence(string $shop,int $id):array|WP_Error {
  $j=$this->read($shop,$id);if($j instanceof WP_Error)return $j;$refs=[];foreach($j['results']as $r)$refs[$r['usage_id']]=['index'=>array_search($r['source_sha256'],$j['identity']['sources'],true),'simulation_usage'=>$r['simulation_usage']??null];
  if($j['usage_id']>0&&!isset($refs[$j['usage_id']]))$refs[$j['usage_id']]=['index'=>$j['index'],'simulation_usage'=>$j['simulation_usage']??null];$items=[];$money=new MonetaryReservationRepository();
  foreach($refs as $usageId=>$r){$index=$r['index'];$c=is_int($index)?($j['identity']['contracts'][$index]??null):null;$h=$money->reservation((int)$usageId);if($h instanceof WP_Error)return $h;if(!is_array($h)||!is_array($c)||$h['shop_key']!==$shop||$h['run_id']!==$j['identity']['run_context']['run_id']||$h['attempt_key']!=='research-queue-'.$id.'-'.$index||$h['request_sha256']!==$c['request_sha256']||$h['model']!==$c['model'])return self::error('cost_identity');
   $snapshot=(new ProviderEvidenceRepository())->snapshot((int)$usageId,$shop);if($snapshot instanceof WP_Error)return $snapshot;$sim=$j['identity']['mode']==='OFFLINE_SIMULATOR';if($sim&&($snapshot['metering']!==null||$snapshot['settlement']!==null))return self::error('simulation_charge_conflict');
   $items[]=['usage_id'=>(int)$usageId,'source_sha256'=>$j['identity']['sources'][$index],'provider'=>$c['provider'],'model'=>$h['model'],'currency'=>$h['currency'],'operator_task_ceiling'=>$j['identity']['options']['per_task_ceiling'],'reserved_maximum'=>$h['maximum_charge'],'actual_charge'=>$sim?null:($snapshot['settlement']['charge']['amount']??null),'charge_finality'=>$sim?'NOT_PROVIDER_USAGE':\DigiForge\AI\FinalProviderStatement::finality($snapshot['settlement']),'observed_provider_usage'=>$sim?null:($snapshot['metering']['usage']??null),'simulated_usage'=>$sim?$r['simulation_usage']:null,'cost_state'=>$sim?'SIMULATED_USAGE_NOT_PROVIDER_CHARGE_RESERVATION_RETAINED':$snapshot['cost_state']];
  }
  $gate=ResearchExecutionJournal::access($shop);return $gate instanceof WP_Error?$gate:['statement_policy_version'=>\DigiForge\AI\FinalProviderStatement::POLICY_VERSION,'job_id'=>$id,'items'=>$items,'refund_assumed'=>false,'external_execution_authorized'=>false];
 }
 /** Local original-statement review through the existing ledger; never infers refunds or provider success. */
 public function reconcile(string $shop,int $id,string $event,int $usageId,string $document,bool $confirmed):array|WP_Error {
  return $this->process($shop,$id,function()use($shop,$id,$event,$usageId,$document,$confirmed){$j=$this->read($shop,$id);if($j instanceof WP_Error)return $j;if(!$confirmed||$j['event_sha256']!==$event||$j['identity']['mode']!=='NETWORK'||strlen($document)<2||strlen($document)>32768)return self::error('statement_admission');$cost=$this->costEvidence($shop,$id);if($cost instanceof WP_Error)return $cost;$matches=array_values(array_filter($cost['items'],static fn($i)=>$i['usage_id']===$usageId));if(count($matches)!==1)return self::error('statement_usage');$snapshot=(new ProviderEvidenceRepository())->snapshot($usageId,$shop);if($snapshot instanceof WP_Error)return $snapshot;$meter=$snapshot['metering'];if(!is_array($meter))return self::error('statement_metering_required');
   $e=\DigiForge\AI\FinalProviderStatement::evidence($document,$meter['response_id']);if($e instanceof WP_Error)return $e;$gate=ResearchExecutionJournal::access($shop);if($gate instanceof WP_Error)return $gate;$receipt=(new ProviderEvidenceRepository())->settle($usageId,$shop,$e);if($receipt instanceof WP_Error)return $receipt;return $this->costEvidence($shop,$id);
  });
 }
 public function cancel(string $shop,int $id,string $expected):array|WP_Error {return $this->process($shop,$id,function()use($id,$expected){$j=new ResearchExecutionJournal();$v=$j->read($id);if($v instanceof WP_Error)return $v;if($v['event_sha256']!==$expected||!in_array($v['state'],['QUEUED','WAITING','UNKNOWN','BLOCKED','HELD','RESERVED'],true))return self::error('cancel_state');return $j->append($id,$expected,['state'=>'CANCELLED']);});}
 public function recover(string $shop,int $id,string $expected):array|WP_Error {return $this->process($shop,$id,function()use($id,$expected){$j=new ResearchExecutionJournal();$v=$j->read($id);if($v instanceof WP_Error)return $v;global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT state,lease_expires_at,last_error FROM '.Tables::jobs().' WHERE id=%d',$id),ARRAY_A);if($v['event_sha256']!==$expected||!is_array($row)||!(($row['state']==='RUNNING'&&is_string($row['lease_expires_at'])&&$row['lease_expires_at']<gmdate('Y-m-d H:i:s'))||($row['state']==='HUMAN_REVIEW'&&($row['last_error']??null)==='LEASE_EXPIRED'&&$row['lease_expires_at']===null))||in_array($v['state'],['AWAITING_REVIEW','CANCELLED','UNKNOWN','BLOCKED','HELD'],true))return self::error('recovery_state');return $j->append($id,$expected,['state'=>'UNKNOWN','failure_class'=>'INTERRUPTED_ATTEMPT_NO_AUTOMATIC_RETRY']);});}
 private function fresh(string $hash,int $days):array|WP_Error {$v=(new CommercialResearchRepository())->read('personalized_pod',$hash);if($v instanceof WP_Error)return $v;if($v['record']['stage']!=='RESEARCH_READY')return self::error('source_stage');foreach($v['record']['research']['sources']as $s){$at=strtotime($s['observed_at']);if($at===false||$at<time()-$days*86400||$at>time())return self::error('stale_source');}return $v;}
 private function claim(int $id,string $state):string|WP_Error {$q=new JobRepository();if($state==='WAITING'&&!$q->transition($id,'HUMAN_REVIEW','QUEUED'))return self::error('queue_claim');$owner='s2_research_'.substr(hash('sha256',$id.'|'.get_current_user_id()),0,40);if(!$q->acquireLease($id,$owner,60)||!$q->start($id,$owner))return self::error('queue_lease');return $owner;}
 private function leaseValid(int $id,string $owner):bool {global $wpdb;$wpdb->last_error='';$row=$wpdb->get_row($wpdb->prepare('SELECT locked_by,lease_expires_at FROM '.Tables::jobs().' WHERE id=%d AND state=%s',$id,'RUNNING'),ARRAY_A);return $wpdb->last_error===''&&is_array($row)&&$row['locked_by']===$owner&&$row['lease_expires_at']>=gmdate('Y-m-d H:i:s');}
 private function process(string $shop,int $id,callable $work):array|WP_Error {$gate=ResearchExecutionJournal::access($shop);if($gate instanceof WP_Error)return $gate;global $wpdb;$connection=$wpdb->get_var('SELECT CONNECTION_ID()');$name='df-research-exec-'.substr(hash('sha256',(string)$wpdb->get_var('SELECT DATABASE()').'|'.$wpdb->prefix.'|'.$id),0,40);$wpdb->last_error='';$lock=$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,0)',$name));if($wpdb->last_error!==''||(string)$lock!=='1')return self::error('busy');try{$result=$work();}catch(\Throwable){$result=self::error('operation_unknown');}finally{$wpdb->last_error='';$owned=$wpdb->get_var($wpdb->prepare('SELECT IS_USED_LOCK(%s)',$name));$released=$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$name));if($wpdb->last_error!==''||(string)$owned!==(string)$connection||(string)$released!=='1')$result=self::error('process_lease_unknown');}$fresh=ResearchExecutionJournal::access($shop);return $fresh instanceof WP_Error?$fresh:$result;}
 private function unknown(array $v,string $reason):WP_Error {$saved=(new ResearchExecutionJournal())->append($v['id'],$v['event_sha256'],['state'=>'UNKNOWN','failure_class'=>$reason]);return $saved instanceof WP_Error?$saved:self::error('outcome_unknown');}
 private static function error(string $code):WP_Error{return ResearchExecutionJournal::error($code);}
}
